import Foundation

/// Best-effort privacy exclusions. Apps do not always label secret clipboard content.
enum ClipboardPrivacy {
    static let excludedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType"
    ]

    private static let passwordManagerIdentifiers: [String] = [
        "1password", "bitwarden", "lastpass", "dashlane",
        "keepass", "proton.pass", "enpass", "strongbox",
        "nordpass", "keepersecurity", "passwordmanager"
    ]

    static func normalizedBundleIDs(from text: String) -> [String] {
        Array(Set(text
            .components(separatedBy: .newlines)
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() }
            .filter { $0.contains(".") && !$0.contains(" ") && $0.count <= 255 }
        )).sorted()
    }

    static func shouldIgnore(bundleID: String, typeNames: [String], customBundleIDs: [String]) -> Bool {
        if typeNames.contains(where: excludedTypes.contains) { return true }
        let identifier = bundleID.lowercased()
        if passwordManagerIdentifiers.contains(where: identifier.contains) { return true }
        return customBundleIDs.contains(identifier)
    }
}

/// Preferences are read when the pasteboard changes, not on every timer tick.
enum ClipboardPreferences {
    static let imagesKey = "clipboard.capture.images"
    static let filesKey = "clipboard.capture.files"
    static let excludedAppsKey = "clipboard.privacy.excludedApps"
    static let retentionDaysKey = "clipboard.retention.days"
    static let retentionCountKey = "clipboard.retention.count"
    static let ocrKey = "clipboard.capture.ocr"

    static func enabled(_ key: String, fallback: Bool = true) -> Bool {
        guard UserDefaults.standard.object(forKey: key) != nil else { return fallback }
        return UserDefaults.standard.bool(forKey: key)
    }

    static var captureImages: Bool { enabled(imagesKey) }
    static var captureFiles: Bool { enabled(filesKey) }
    /// CPU-intensive, opt-in on-device text recognition for copied images.
    static var recognizeImages: Bool { enabled(ocrKey, fallback: false) }
    static var excludedBundleIDs: [String] {
        ClipboardPrivacy.normalizedBundleIDs(
            from: UserDefaults.standard.string(forKey: excludedAppsKey) ?? ""
        )
    }
    static var retentionDays: Int {
        guard UserDefaults.standard.object(forKey: retentionDaysKey) != nil else { return 30 }
        return min(max(UserDefaults.standard.integer(forKey: retentionDaysKey), 1), 365)
    }
    static var retentionCount: Int {
        guard UserDefaults.standard.object(forKey: retentionCountKey) != nil else { return 1000 }
        return min(max(UserDefaults.standard.integer(forKey: retentionCountKey), 50), 5000)
    }
}
